#!/bin/bash
# r7886+60, on order `r7885` (69) item ①: ** THE TEN LENSING POINTS, ONE PER JOB, FOR A RUNNER. **
#
# ⚑ NOTHING IS RETYPED HERE.  The point list and every point's environment live in `points.json`,
#   which was GENERATED by reading `r7884`'s own generator, and `verify_grid.py`'s closure `Ⓒ⓹`
#   re-reads both and refuses if they have drifted apart.  This file only dispatches.
# ⚑ IDEMPOTENT AND RESUMABLE: a point whose `.json` is already in `$PPOUT` is skipped, so splitting
#   the ten across several runner jobs costs nothing and a re-run after a timeout resumes.
# ⛔ JOBS=1 IS A MEASUREMENT, NOT A PREFERENCE.  One point is ~35 min wall and ~2h16m CPU on ~3.95
#   cores: the solve is threaded and one point already uses a 4-core box.  Four at once
#   oversubscribed such a box ~16-fold and in five attempts NO leg ever finished.
#
# Usage, from anywhere:
#     PPOUT=<dir> [ONLY="lcdm_S006 cr_S015"] [MAXP=N] bash launch.sh
#   PPOUT  where the points are written AND read for the skip test (default: the checkout's bank).
#   ONLY   run only these `arm_tag` points, for splitting across jobs.  Unset runs all outstanding.
#   MAXP   stop after N points have been RUN this invocation, for fitting a job's timeout.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
BTW=$(cd "$HERE/.." && pwd)
DRIVER_DIR="$BTW/r7846_60_the_scale_dependent_growth_and_the_banked_lensing_bandpowers"
OUT=${PPOUT:-"$BTW/bank/$(python3 -c "import json,io;print(json.load(io.open('$HERE/points.json'))['out_dir_name'])")"}
ONLY=${ONLY:-}
MAXP=${MAXP:-99}
mkdir -p "$OUT"
# ⛔ RESOLVE $OUT TO AN ABSOLUTE PATH BEFORE THE `cd` BELOW.  This was a real bug, caught by running
#   the script rather than reading it: with a RELATIVE `PPOUT` the skip test and the final count
#   both looked in the wrong place after the `cd`, so an already-banked point was re-run and the
#   tail line reported "0 of 10 banked" while ten were sitting on disk.  That is the same silent
#   miscount that once pointed this family of generators at the landed grid instead of its own.
OUT=$(cd "$OUT" && pwd) || { echo "  ⛔ cannot resolve PPOUT=$OUT"; exit 1; }
# ⌗ one point already takes the whole box; letting BLAS thread inside it is what we want, and
#   what we must NOT do is run two points at once.  So no thread pinning here, unlike a fan-out.
cd "$DRIVER_DIR" || exit 1
echo "=== r7886 LAUNCH  out=$OUT  only='${ONLY:-<all>}'  maxp=$MAXP  $(date -u) ==="
ran=0
while read -r arm tag envline; do
  key="${arm}_${tag}"
  [ -n "$ONLY" ] && ! printf '%s\n' $ONLY | grep -qx "$key" && continue
  if [ -s "$OUT/$key.json" ]; then echo "  skip $key (banked)"; continue; fi
  if [ "$ran" -ge "$MAXP" ]; then
    # ⌗ MAXP=0 is a DRY RUN: it names the next point it would run and stops, so `70` can check the
    #   wiring and the selection without spending the ~35 minutes a real point costs.
    echo "  would run $key next; stopping: MAXP=$MAXP reached"; break
  fi
  echo "  run  $key  $(date -u +%H:%M:%S)"
  # shellcheck disable=SC2086
  env $envline PPOUT="$OUT" python3 -u phiphi_point.py > "$OUT/$key.log" 2>&1
  rc=$?
  echo "  $arm $tag rc=$rc" >> "$OUT/done.txt"
  tail -1 "$OUT/$key.log"
  ran=$((ran+1))
done < <(python3 - "$HERE/points.json" <<'PY'
import io, json, sys
d = json.load(io.open(sys.argv[1], encoding='utf-8'))
for p in d['points']:
    env = ' '.join('%s=%s' % (k, v) for k, v in sorted(p['env'].items()))
    print('%s %s %s' % (p['arm'], p['tag'], env))
PY
)
echo "=== r7886 LAUNCH DONE: $ran point(s) run this invocation; $(ls "$OUT"/*.json 2>/dev/null | wc -l) of 10 banked  $(date -u) ==="
